package visit

import (
	"slices"

	"rimworld-go/internal/domain/combat/kit"
	"rimworld-go/internal/domain/faction"
	"rimworld-go/internal/domain/sim/entity"
)

// CaravanArrival makes an entire trading party from one map entry. The
// stock is generated by the trading owner after the members are placed.
type CaravanArrival struct {
	GroupID uint64
	Trader  entity.EntityID
	Members []entity.EntityID
}

// ArriveCaravan registers a trader, guards and an optional pack animal.
// The caller owns the trade ledger; visit owns the people and their jobs.
func (v Visits) ArriveCaravan(ref int, f *faction.Faction, now, duration uint64, small bool, n int,
	place func(ex, ey int, used [][2]int) (int, int, bool)) (CaravanArrival, bool) {
	ex, ey, ok := v.h.Edge()
	if !ok {
		return CaravanArrival{}, false
	}
	var used [][2]int
	ids := make([]entity.EntityID, 0, n)
	ms := make([]Member, 0, n+1)
	for k := 0; k < n; k++ {
		fromX, fromY := ex, ey
		if len(used) > 0 {
			fromX, fromY = used[0][0], used[0][1]
		}
		var x, y int
		var ok bool
		if place != nil {
			x, y, ok = place(fromX, fromY, used)
		} else {
			x, y, ok = v.InsetLand(ex, ey, used)
		}
		if !ok {
			break
		}
		used = append(used, [2]int{x, y})
		id := v.Spawn(ref, f, x, y, now)
		v.SetStay(id, now+duration)
		role := RoleGuard
		if small {
			role = RoleVisitor
		}
		if k == 0 {
			role = RoleTrader
		} else if !small {
			v.h.Arm(id, kit.Ally(faction.DefOf(f.Type).Tech, k))
		}
		ids = append(ids, id)
		ms = append(ms, Member{ID: id, Role: role})
	}
	if len(ids) == 0 {
		return CaravanArrival{}, false
	}
	if !small {
		if x, y, ok := v.InsetLand(ex, ey, used); ok {
			if animal, ok := v.h.PackAnimal(x, y); ok {
				ms = append(ms, Member{ID: animal, Role: RolePackAnimal})
			}
		}
	}
	group := v.NewGroup(KindCaravan, ref, ms, now, now+duration)
	if small {
		for i := range *v.h.Groups(true) {
			if (*v.h.Groups(true))[i].ID == group {
				(*v.h.Groups(true))[i].Kind = KindSmallTrader
				break
			}
		}
	}
	slices.Sort(ids)
	return CaravanArrival{GroupID: group, Trader: ms[0].ID, Members: ids}, true
}
